'use client'

import { PromptInputActionAddAttachments, PromptInputActionAddFolder, PromptInputButton } from '@/components/ai-elements/prompt-input'
import { Button } from '@/components/ui/button'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuSub, DropdownMenuSubContent, DropdownMenuSubTrigger, DropdownMenuTrigger } from '@/components/ui/dropdown-menu'
import type { AccessMode } from '@/lib/chat-sessions'
import type { AgentKind } from '@/lib/chat-session-types'
import type { CodexComposerResources, CodexPluginResource, CodexSkillResource, RuntimeComposerResources } from '@/lib/composer-resources'
import type { UserSkill } from '@/lib/user-skill-types'
import { codexPluginToken, codexSkillToken, piSkillToken } from '@/lib/prompt-input-protocol'
import { useT } from '@/lib/i18n/client'
import { cn } from '@/lib/utils'
import FigmaColor from '@lobehub/icons/es/Figma/components/Color'
import GithubMono from '@lobehub/icons/es/Github/components/Mono'
import { BookOpen, Check, ExternalLink, Folder, Import, Monitor, Network, PackagePlus, PanelsTopLeft, Plus, Shapes, ShieldCheck, UploadCloud, Zap } from 'lucide-react'
import { useMemo, useState } from 'react'

export interface PromptAddMenuProps {
  variant: 'home' | 'session'
  className?: string
  agent?: AgentKind
  skills?: UserSkill[]
  customInstructions?: string
  runtimeResources?: RuntimeComposerResources | null
  accessMode?: AccessMode
  codexResources?: CodexComposerResources | null
  onInsertText?: (text: string) => void
  onAddInstruction?: (name: string, text: string) => void
  onAccessModeChange?: (mode: AccessMode) => void
  accessModeChangeDisabled?: boolean
  onInstallPlugin?: (pluginId: string) => Promise<void>
  pluginInstallationDisabled?: boolean
  attachmentsEnabled?: boolean
}

const itemClassName = 'h-8 cursor-pointer gap-2 rounded-lg px-3 text-[14px] font-normal leading-5 text-[var(--app-foreground)] focus:bg-[var(--app-hover)] focus:text-[var(--app-foreground)]'
const iconClassName = 'size-4 text-[var(--app-muted)]'
const subMenuClassName = 'max-h-[min(60vh,420px)] overflow-y-auto overscroll-contain rounded-xl border border-[var(--app-border)] bg-[var(--app-elevated)] p-[7px] text-[var(--app-foreground)] shadow-[0_10px_28px_var(--app-shadow)] ring-0'

function MenuHint({ children }: { children: React.ReactNode }) {
  return <div className="px-3 py-2 text-xs font-normal text-[var(--app-muted)]" role="status">{children}</div>
}

function PluginDialog({ open, onOpenChange, plugins, onInstall, installationDisabled = false }: { open: boolean; onOpenChange: (open: boolean) => void; plugins: CodexPluginResource[]; onInstall?: (pluginId: string) => Promise<void>; installationDisabled?: boolean }) {
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [installingId, setInstallingId] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const t = useT()
  const selected = plugins.find((plugin) => plugin.pluginId === selectedId) ?? null
  const available = useMemo(() => [...plugins].sort((a, b) => Number(b.installed) - Number(a.installed) || a.displayName.localeCompare(b.displayName)), [plugins])
  async function install() {
    if (!selected || !onInstall || installationDisabled) return
    setInstallingId(selected.pluginId); setError(null)
    try { await onInstall(selected.pluginId) } catch (cause) { setError(cause instanceof Error ? cause.message : t('插件安装失败，请稍后重试。')) } finally { setInstallingId(null) }
  }
  return <Dialog onOpenChange={(nextOpen) => { onOpenChange(nextOpen); if (!nextOpen) { setSelectedId(null); setError(null) } }} open={open}>
    <DialogContent className="h-[min(68vh,620px)] grid-rows-[auto_minmax(0,1fr)] gap-0 overflow-hidden rounded-2xl border border-[var(--app-border)] bg-[var(--app-elevated)] p-0 text-[var(--app-foreground)] shadow-[0_24px_64px_var(--app-shadow)] ring-0" style={{ width: 'min(1100px, calc(100vw - 64px))', maxWidth: '1100px' }}>
      <DialogHeader className="border-b border-[var(--app-border)] px-5 py-4 pr-12"><DialogTitle>{t("Codex 插件市场")}</DialogTitle><DialogDescription className="text-[var(--app-muted)]">{t('从当前 Codex 已配置的 marketplace 读取；详情来自插件的')}{' '}<code>.codex-plugin/plugin.json</code>{t('。')}</DialogDescription></DialogHeader>
      {!selected ? <div className="grid min-h-0 grid-cols-1 gap-3 overflow-y-auto p-5 sm:grid-cols-2 lg:grid-cols-3">{available.length ? available.map((plugin) => <button className="flex min-h-40 flex-col items-start rounded-xl border border-[var(--app-border)] bg-[var(--app-surface)] p-4 text-left transition-colors hover:bg-[var(--app-hover)]" key={plugin.pluginId} onClick={() => { setSelectedId(plugin.pluginId); setError(null) }} type="button"><span className="flex w-full items-start gap-3"><span className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-[var(--app-active)]"><PackagePlus className="size-4 text-[var(--app-muted)]" /></span><span className="min-w-0 flex-1"><span className="flex items-center gap-2"><span className="truncate font-medium">{plugin.displayName}</span>{plugin.installed && <span className="rounded-full bg-[var(--app-active)] px-1.5 py-0.5 text-[10px] text-[var(--app-muted)]">{t("已安装")}</span>}</span><span className="mt-2 block line-clamp-3 text-xs leading-5 text-[var(--app-muted)]">{plugin.shortDescription || t("Codex 插件")}</span></span></span><span className="mt-auto pt-3 text-[11px] text-[var(--app-muted)]">{plugin.marketplaceName} · v{plugin.version}</span></button>) : <MenuHint>{t("当前 Codex 未返回可用插件。")}</MenuHint>}</div> : <div className="min-h-0 overflow-y-auto p-5"><button className="mb-4 text-xs text-[var(--app-muted)] hover:text-[var(--app-foreground)]" onClick={() => { setSelectedId(null); setError(null) }} type="button">{t("← 返回插件列表")}</button><div className="flex items-start gap-3"><span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-[var(--app-active)]"><PackagePlus className="size-5 text-[var(--app-muted)]" /></span><div className="min-w-0"><h3 className="text-lg font-semibold">{selected.displayName}</h3><p className="mt-1 text-sm leading-6 text-[var(--app-muted)]">{selected.longDescription || selected.shortDescription || t("Codex 插件")}</p></div></div><dl className="mt-5 grid grid-cols-2 gap-x-5 gap-y-3 text-sm"><div><dt className="text-xs text-[var(--app-muted)]">{t("插件 ID")}</dt><dd className="mt-0.5 break-all">{selected.pluginId}</dd></div><div><dt className="text-xs text-[var(--app-muted)]">{t("版本")}</dt><dd className="mt-0.5">{selected.version || t("未声明")}</dd></div>{selected.developerName && <div><dt className="text-xs text-[var(--app-muted)]">{t("开发者")}</dt><dd className="mt-0.5">{selected.developerName}</dd></div>}{selected.category && <div><dt className="text-xs text-[var(--app-muted)]">{t("分类")}</dt><dd className="mt-0.5">{selected.category}</dd></div>}{selected.license && <div><dt className="text-xs text-[var(--app-muted)]">{t("许可证")}</dt><dd className="mt-0.5">{selected.license}</dd></div>}{selected.capabilities.length > 0 && <div><dt className="text-xs text-[var(--app-muted)]">{t("能力")}</dt><dd className="mt-0.5">{selected.capabilities.join(" · ")}</dd></div>}</dl>{selected.keywords.length > 0 && <div className="mt-5 flex flex-wrap gap-1.5">{selected.keywords.map((keyword) => <span className="rounded-full bg-[var(--app-active)] px-2 py-1 text-xs text-[var(--app-muted)]" key={keyword}>{keyword}</span>)}</div>}{selected.defaultPrompts.length > 0 && <div className="mt-5"><p className="text-xs text-[var(--app-muted)]">{t("默认提示词")}</p><ul className="mt-2 space-y-1.5 text-sm text-[var(--app-foreground)]">{selected.defaultPrompts.map((prompt) => <li key={prompt}>• {prompt}</li>)}</ul></div>}{(selected.websiteUrl || selected.homepage || selected.repository || selected.privacyPolicyUrl || selected.termsOfServiceUrl) && <div className="mt-5 flex flex-wrap gap-3 text-xs">{[[selected.websiteUrl || selected.homepage, t("网站")], [selected.repository, t("仓库")], [selected.privacyPolicyUrl, t("隐私")], [selected.termsOfServiceUrl, t("条款")]].flatMap(([href, label]) => typeof href === "string" ? [<a className="inline-flex items-center gap-1 text-[var(--app-brand)] hover:underline" href={href} key={label} rel="noreferrer" target="_blank">{label}<ExternalLink className="size-3" /></a>] : [])}</div>}{error && <p className="mt-4 text-sm text-[var(--app-danger)]" role="alert">{error}</p>}<div className="mt-6 flex justify-end gap-2">{selected.installed ? <Button disabled size="sm" variant="secondary"><Check />{t("已安装")}{selected.enabled ? t("并启用") : ''}</Button> : <Button disabled={installationDisabled || installingId === selected.pluginId || selected.installPolicy !== "AVAILABLE"} onClick={() => void install()} size="sm">{installingId === selected.pluginId ? t("正在安装并加载…") : installationDisabled ? t("当前回复结束后可安装") : selected.installPolicy === "AVAILABLE" ? t("安装插件") : t("此插件不可安装")}</Button>}</div></div>}
    </DialogContent>
  </Dialog>
}

export function PromptAddMenu({ variant, className, agent, skills = [], customInstructions = '', runtimeResources, accessMode, codexResources, onInsertText, onAddInstruction, onAccessModeChange, accessModeChangeDisabled = false, onInstallPlugin, pluginInstallationDisabled = false, attachmentsEnabled = false }: PromptAddMenuProps) {
  const [menuOpen, setMenuOpen] = useState(false)
  const [pluginsOpen, setPluginsOpen] = useState(false)
  const t = useT()
  const isHome = variant === 'home'
  const runtimeName = runtimeResources?.source ?? (agent === 'pi' ? 'Pi Agent' : agent === 'omp' ? 'Oh My Pi Agent' : 'Codex Agent')
  // Persisted session state is available before an on-demand runtime is
  // leased. Once the worker reports its policy, it becomes the source of
  // truth; this fallback keeps the selector actionable during warmup.
  const permissions = runtimeResources?.accessMode ?? accessMode
  const codexSkills = codexResources?.skills ?? []
  const installedPlugins = (codexResources?.plugins ?? []).filter((plugin) => plugin.installed && plugin.enabled)
  const runtimeInstructions = runtimeResources?.instructions ?? []
  const computer = runtimeResources?.computer
  // Pi's runtime skills live in the sandbox image, while saved User Skills
  // live in the app database. Show both without duplicating a shared name.
  const piSkills = agent === 'pi'
    ? [
        ...(runtimeResources?.skills ?? []).map((skill) => ({ id: skill.id, slug: skill.name, description: skill.description, source: t('运行时') })),
        ...skills
          .filter((skill) => !(runtimeResources?.skills ?? []).some((runtime) => runtime.name === skill.slug))
          .map((skill) => ({ id: skill.id, slug: skill.slug, description: skill.content.replace(/\s+/g, ' ').trim().slice(0, 120), source: t('已保存') })),
      ]
    : []
  const mcpServers = runtimeResources?.mcpServers ?? []
  const nativePermissions = (runtimeResources?.permissionProfiles ?? []).filter((profile) => !['restricted', 'ask', 'open'].includes(profile.id))
  const permissionLabel = permissions === 'restricted' ? t('受限') : permissions === 'ask' ? t('询问') : permissions === 'open' ? t('开放') : t('加载中')
  return <><DropdownMenu onOpenChange={setMenuOpen} open={menuOpen}><DropdownMenuTrigger render={<PromptInputButton aria-label={t("打开添加菜单")} className={cn('size-7 shrink-0 rounded-md p-0 transition-[color,background-color,border-color,opacity] active:translate-y-0!', isHome ? 'text-[var(--app-muted)] hover:bg-[var(--app-hover)]' : 'text-[var(--app-muted)] hover:bg-[var(--app-active)] hover:text-[var(--app-foreground)]', className)} type="button" />}>{isHome ? <img alt="" className="app-control-icon size-4" src="/openlink/app/plus.svg" /> : <Plus aria-hidden className="size-4" />}</DropdownMenuTrigger><DropdownMenuContent align="start" className="w-[270px] rounded-xl border border-[var(--app-border)] bg-[var(--app-elevated)] p-[7px] text-[var(--app-foreground)] shadow-[0_10px_28px_var(--app-shadow)] ring-0" side="top" sideOffset={8}>
    <div className="flex items-center justify-between gap-2 px-3 pb-1.5 pt-1 text-[11px] text-[var(--app-muted)]">
      <span className="min-w-0 truncate">{runtimeName}</span>
      <span className="flex shrink-0 items-center gap-1.5"><span>{permissionLabel}</span><span aria-hidden className="size-1 rounded-full bg-[var(--app-subtle-foreground)]" /><span>{t('{count} MCP', { count: mcpServers.length })}</span></span>
    </div>
    <DropdownMenuSub><DropdownMenuSubTrigger className={cn(itemClassName, "data-popup-open:bg-[var(--app-hover)] data-popup-open:text-[var(--app-foreground)] [&>svg:last-child]:size-4 [&>svg:last-child]:text-[var(--app-muted)]")}><Import aria-hidden className={iconClassName} /><span>{t('导入来源')}</span><span aria-hidden className="ml-auto flex items-center gap-1 text-[var(--app-muted)]">{isHome && <GithubMono size={14} />}<FigmaColor size={14} /><PanelsTopLeft className="size-3.5 text-blue-500" /></span></DropdownMenuSubTrigger><DropdownMenuSubContent className={cn("w-[210px]", subMenuClassName)}>{isHome && <DropdownMenuItem className={itemClassName} disabled><GithubMono aria-hidden size={16} /><span>{t("GitHub（即将推出）")}</span></DropdownMenuItem>}<DropdownMenuItem className={itemClassName} disabled><FigmaColor aria-hidden size={16} /><span>{t("Figma（即将推出）")}</span></DropdownMenuItem><DropdownMenuItem className={itemClassName} disabled><PanelsTopLeft aria-hidden className={cn(iconClassName, "text-blue-500")} /><span>{t("Design file（即将推出）")}</span></DropdownMenuItem></DropdownMenuSubContent></DropdownMenuSub>
    {attachmentsEnabled ? <><PromptInputActionAddAttachments className={itemClassName} label={t('上传文件')}><UploadCloud aria-hidden className={iconClassName} /><span>{t('上传文件')}</span></PromptInputActionAddAttachments>{!isHome && <PromptInputActionAddFolder className={itemClassName} label={t('上传文件夹')}><Folder aria-hidden className={iconClassName} /><span>{t('上传文件夹')}</span></PromptInputActionAddFolder>}</> : null}<DropdownMenuSeparator className="-mx-[7px] my-[7px] bg-[var(--app-border)]" />
    {agent !== 'omp' && <DropdownMenuSub><DropdownMenuSubTrigger className={itemClassName}><Zap aria-hidden className={iconClassName} /><span className="min-w-0 flex-1">{t('Skills')}</span><span className="w-7 text-right text-[11px] tabular-nums text-[var(--app-muted)]">{(agent === "codex" ? (codexSkills.length || (runtimeResources?.skills ?? []).length || 0) : piSkills.length) || ""}</span></DropdownMenuSubTrigger><DropdownMenuSubContent className={cn("w-[320px]", subMenuClassName)}>{agent === "codex" && <><MenuHint>{t("Codex 原生 Skills · 选择后插入 $Skill")}</MenuHint>{(codexSkills.length ? codexSkills.map((skill: CodexSkillResource) => ({ id: skill.id, name: skill.name, description: skill.description, source: skill.source === 'builtin' ? t('内置') : t('插件') })) : (runtimeResources?.skills ?? []).map((skill) => ({ id: skill.id, name: skill.name, description: skill.description, source: skill.source === 'plugin' ? t('插件') : t('内置') }))).map((skill) => <DropdownMenuItem className={itemClassName} key={skill.id} onClick={() => onInsertText?.(codexSkillToken(skill.name))}><Zap aria-hidden className={iconClassName} /><span className="min-w-0 flex-1"><span className="block truncate">${skill.name}</span>{skill.description && <span className="block truncate text-[10px] text-[var(--app-muted)]">{skill.description}</span>}</span><span className="shrink-0 text-[10px] text-[var(--app-muted)]">{skill.source}</span></DropdownMenuItem>)}{!codexSkills.length && !(runtimeResources?.skills ?? []).length && <MenuHint>{t("正在读取 Codex 已安装技能。")}</MenuHint>}</>}{agent === "pi" && piSkills.length > 0 && <><MenuHint>{t("Pi 原生 Skills · 选择后插入 /skill:name")}</MenuHint>{piSkills.map((skill) => <DropdownMenuItem className={itemClassName} key={skill.id} onClick={() => onInsertText?.(piSkillToken(skill.slug))}><Zap aria-hidden className={iconClassName} /><span className="min-w-0 flex-1"><span className="block truncate">/skill:{skill.slug}</span>{skill.description && <span className="block truncate text-[10px] text-[var(--app-muted)]">{skill.description}</span>}</span><span className="shrink-0 text-[10px] text-[var(--app-muted)]">{skill.source}</span></DropdownMenuItem>)}</>}{agent === "pi" && !piSkills.length && <MenuHint>{t("尚未发现 Pi 技能，可在设置中创建，或检查运行时 Skills。")}</MenuHint>}</DropdownMenuSubContent></DropdownMenuSub>}
    {agent === 'codex' && <DropdownMenuSub><DropdownMenuSubTrigger className={itemClassName}><PackagePlus aria-hidden className={iconClassName} /><span className="min-w-0 flex-1">{t('插件')}</span><span className="w-7 text-right text-[11px] tabular-nums text-[var(--app-muted)]">{installedPlugins.length || ''}</span></DropdownMenuSubTrigger><DropdownMenuSubContent className={cn('w-[310px]', subMenuClassName)}><MenuHint>{t("Codex 已启用 Plugins · 选择后插入 @Plugin")}</MenuHint>{installedPlugins.map((plugin) => <DropdownMenuItem className={itemClassName} key={plugin.pluginId} onClick={() => onInsertText?.(codexPluginToken(plugin.name, plugin.displayName))}><PackagePlus aria-hidden className={iconClassName} /><span className="min-w-0 flex-1 truncate">{codexPluginToken(plugin.name, plugin.displayName).trim()}</span><span className="max-w-24 truncate text-[10px] text-[var(--app-muted)]">{plugin.displayName}</span></DropdownMenuItem>)}{installedPlugins.length > 0 && <DropdownMenuSeparator className="my-1 bg-[var(--app-border)]" />}<DropdownMenuItem className={itemClassName} onClick={() => { setMenuOpen(false); setPluginsOpen(true) }}><PackagePlus aria-hidden className={iconClassName} /><span>{t("管理 Codex 插件")}</span></DropdownMenuItem></DropdownMenuSubContent></DropdownMenuSub>}{isHome && <DropdownMenuItem className={itemClassName} disabled><Shapes aria-hidden className={iconClassName} /><span>{t("Design Systems（即将推出）")}</span></DropdownMenuItem>}{isHome && <DropdownMenuItem className={itemClassName} disabled><Folder aria-hidden className={iconClassName} /><span>{t("Folder（即将推出）")}</span></DropdownMenuItem>}
    <DropdownMenuSub><DropdownMenuSubTrigger className={itemClassName}><BookOpen aria-hidden className={iconClassName} /><span className="min-w-0 flex-1">{t('指令')}</span><span className="w-7 text-right text-[11px] tabular-nums text-[var(--app-muted)]">{(runtimeInstructions.length + (customInstructions.trim() ? 1 : 0)) || ''}</span></DropdownMenuSubTrigger><DropdownMenuSubContent className={cn('w-[320px]', subMenuClassName)}>{customInstructions.trim() && <DropdownMenuItem className={itemClassName} onClick={() => onAddInstruction?.(t("已保存的自定义指令"), customInstructions.trim())}><BookOpen aria-hidden className={iconClassName} /><span className="min-w-0 flex-1"><span className="block truncate">{t("已保存的自定义指令")}</span><span className="block truncate text-[10px] text-[var(--app-muted)]">{t('用户偏好 · 添加到本次提示')}</span></span></DropdownMenuItem>}{runtimeInstructions.map((instruction) => <DropdownMenuItem className={itemClassName} key={instruction.id} onClick={() => onAddInstruction?.(instruction.name, instruction.text)}><BookOpen aria-hidden className={iconClassName} /><span className="min-w-0 flex-1"><span className="block truncate">{instruction.name}</span>{instruction.description && <span className="block truncate text-[10px] text-[var(--app-muted)]">{instruction.description}</span>}</span></DropdownMenuItem>)}{!customInstructions.trim() && !runtimeInstructions.length && <MenuHint>{t("未发现项目指令文件或自定义指令。")}</MenuHint>}</DropdownMenuSubContent></DropdownMenuSub>
    <DropdownMenuSub><DropdownMenuSubTrigger className={itemClassName}><Network aria-hidden className={iconClassName} /><span className="min-w-0 flex-1">MCPs</span><span className="w-7 text-right text-[11px] tabular-nums text-[var(--app-muted)]">{runtimeResources ? mcpServers.length : ''}</span></DropdownMenuSubTrigger><DropdownMenuSubContent className={cn("w-[330px]", subMenuClassName)}><MenuHint>{!runtimeResources ? t("正在读取当前会话运行时") : agent === "codex" ? t("Codex 原生 MCP 状态；认证问题会在使用时请求") : t("{runtime} 原生 MCP inventory", { runtime: String(runtimeName) })}</MenuHint>{mcpServers.length ? mcpServers.map((server) => {
      const authLabel = server.auth === 'required' ? t('需要登录') : server.auth === 'unsupported' ? t('不支持认证') : t('已认证')
      const statusLabel = server.status === 'disabled' ? t('已停用') : server.status === 'error' ? t('连接失败') : t('已连接')
      return <DropdownMenuItem className={itemClassName} disabled={server.status === 'disabled'} key={server.id}><span aria-hidden className={cn('size-1.5 shrink-0 rounded-full', server.status === 'connected' ? 'bg-emerald-500' : server.status === 'error' ? 'bg-[var(--app-danger)]' : 'bg-[var(--app-subtle-foreground)]')} /><span className="min-w-0 flex-1"><span className="block truncate">{server.name}</span><span className="block truncate text-[10px] text-[var(--app-muted)]">{statusLabel} · {authLabel}{(server.toolCount ?? 0) > 0 ? ` · ${t('{count} tools', { count: server.toolCount ?? 0 })}` : ''}</span></span><span className="shrink-0 text-[10px] text-[var(--app-muted)]">{t("原生")}</span></DropdownMenuItem>
    }) : runtimeResources ? <MenuHint>{t("当前会话没有已连接的 MCP。")}</MenuHint> : null}</DropdownMenuSubContent></DropdownMenuSub>
    <DropdownMenuSub><DropdownMenuSubTrigger className={itemClassName} disabled={accessModeChangeDisabled}><ShieldCheck aria-hidden className={iconClassName} /><span className="min-w-0 flex-1">{t("权限")}</span><span className="w-14 text-right text-[11px] text-[var(--app-muted)]">{permissionLabel}</span></DropdownMenuSubTrigger><DropdownMenuSubContent className={cn("w-[300px]", subMenuClassName)}><MenuHint>{t('沙箱与审批策略')}</MenuHint>{(["restricted", "ask", "open"] as AccessMode[]).map((mode) => <DropdownMenuItem className={itemClassName} disabled={accessModeChangeDisabled || permissions === mode} key={mode} onClick={() => { setMenuOpen(false); onAccessModeChange?.(mode) }}><ShieldCheck aria-hidden className={cn(iconClassName, permissions === mode && "text-[var(--app-brand)]")} /><span className="min-w-0 flex-1">{mode === "restricted" ? t("受限（只读）") : mode === "ask" ? t("询问（写操作确认）") : t("开放（完全访问）")}</span>{permissions === mode && <Check aria-hidden className="size-3.5 text-[var(--app-brand)]" />}</DropdownMenuItem>)}{nativePermissions.length > 0 && <><DropdownMenuSeparator className="my-1 bg-[var(--app-border)]" /><MenuHint>{t('Codex 原生 Permission Profiles')}</MenuHint>{nativePermissions.map((profile) => <DropdownMenuItem className={itemClassName} key={profile.id} onClick={() => onInsertText?.(`/permissions ${profile.id} `)}><ShieldCheck aria-hidden className={iconClassName} /><span className="min-w-0 flex-1"><span className="block truncate">{profile.label}</span>{profile.description && <span className="block truncate text-[10px] text-[var(--app-muted)]">{profile.description}</span>}</span></DropdownMenuItem>)}</>}</DropdownMenuSubContent></DropdownMenuSub>
    <DropdownMenuItem className={itemClassName} disabled={!computer?.available}><Monitor aria-hidden className={iconClassName} /><span className="min-w-0 flex-1">{t('Computer')}</span><span className="text-[10px] text-[var(--app-muted)]">{computer?.available ? [computer.desktop ? t('Desktop') : null, computer.browser ? t('Browser') : null].filter(Boolean).join(' · ') : t('不可用')}</span></DropdownMenuItem>
  </DropdownMenuContent></DropdownMenu><PluginDialog installationDisabled={pluginInstallationDisabled} onInstall={onInstallPlugin} onOpenChange={setPluginsOpen} open={pluginsOpen} plugins={codexResources?.plugins ?? []} /></>
}
